  function remove(item){if(!confirm(`Delete “${item.name}” and its payment history?`))return;change(s=>{s.debts=s.debts.filter(x=>x.id!==item.id);s.debtPayments=s.debtPayments.filter(x=>x.debtId!==item.id);s.allocationRules=s.allocationRules.filter(x=>!(x.targetType==='debt'&&x.targetId===item.id));return s},'Repayment deleted')}
  return <div><h2 className="text-3xl font-bold">Money to Pay Back</h2><div className="f-grid f-stats mt-5"><Stat label="Outstanding" amount={summary.outstanding} currency={currency} tone="amber"/><Stat label="Paid this month" amount={summary.paidThisMonth} currency={currency} tone="green"/><Stat label="Active repayments" text={String(data.debts.filter(d=>d.status==='active').length)}/></div>{error&&<p className="f-alert">{error}</p>}<div className="f-grid f-section-grid mt-5"><section className="f-list">{data.debts.length?data.debts.map(d=><article className="f-item" key={d.id}><div className="f-between"><div><p className="f-item-title">{d.name}</p><p className="f-meta">Due {d.dueDate||'date not set'} · {d.priority} priority · {d.status}</p></div><span className="f-tag"><Money amount={d.remaining} currency={currency}/> left</span></div><Progress value={d.original?Math.round((d.original-d.remaining)*10000/d.original):0}/><div className="f-actions mt-3"><button className="f-primary" disabled={!d.remaining} onClick={()=>pay(d)}>Record payment</button><button className={btn} onClick={()=>begin(d)}>Edit</button><button className={btn} onClick={()=>remove(d)}>Delete</button></div></article>):<Empty>No repayments to track.</Empty>}</section><form className="f-card f-form" onSubmit={save}><h3>{editing?'Edit money to pay back':'Add money to pay back'}</h3><label>Person or organisation<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><div className="f-row"><label>Original amount<input required inputMode="decimal" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label>{editing?<label>Amount left<input required inputMode="decimal" value={form.remaining} onChange={e=>setForm({...form,remaining:e.target.value})}/></label>:<label>Due date<input type="date" value={form.dueDate} onChange={e=>setForm({...form,dueDate:e.target.value})}/></label>}</div>{editing&&<label>Due date<input type="date" value={form.dueDate} onChange={e=>setForm({...form,dueDate:e.target.value})}/></label>}<label>Planned payment amount<input inputMode="decimal" value={form.planned} onChange={e=>setForm({...form,planned:e.target.value})}/></label><div className="f-row"><label>Frequency<select value={form.frequency} onChange={e=>setForm({...form,frequency:e.target.value})}>{['weekly','fortnightly','monthly','yearly'].map(x=><option key={x}>{x}</option>)}</select></label><label>Priority<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{['low','medium','high'].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="f-actions"><button className="f-primary">{editing?'Save changes':'Add repayment'}</button>{editing&&<button type="button" className={btn} onClick={()=>{setEditing('');setForm(blankDebt)}}>Cancel</button>}</div></form></div></div>
