const newDebtDraft = settings => ({name:'',amount:'',remaining:'',currency:settings.defaultForeignCurrency||settings.currency,dueDate:'',planned:'',frequency:'monthly',priority:'medium',notes:''});
function DebtsManager({data,month,change,requestMoney,confirmAction}) {
  const base=data.settings.currency,summary=debtSummary(data.debts,data.debtPayments,month);
  const [form,setForm]=useState(()=>newDebtDraft(data.settings)),[editing,setEditing]=useState(''),[error,setError]=useState('');
  const preview=useCurrencyPreview(form.amount,form.currency,base);
  function begin(item){const source=item.sourceCurrency||base;setEditing(item.id);setForm({name:item.name,amount:moneyInput(item.sourceOriginal??item.original),remaining:moneyInput(item.sourceRemaining??item.remaining),currency:source,dueDate:item.dueDate||'',planned:item.plannedAmount?moneyInput(item.plannedAmount):'',frequency:item.frequency,priority:item.priority,notes:item.notes||''});}
  async function save(e){e.preventDefault();try{const sourceOriginal=parseMoney(form.amount),sourceRemaining=form.remaining?nonNegativeMoney(form.remaining):sourceOriginal,quote=await getCurrencyQuote(form.currency,base),original=convertMinorUnits(sourceOriginal,quote.rate),remaining=convertMinorUnits(sourceRemaining,quote.rate),plannedAmount=form.planned?nonNegativeMoney(form.planned):0;await change(s=>{const record={name:form.name.trim(),original,remaining,sourceCurrency:form.currency,sourceOriginal,sourceRemaining,exchangeRate:quote.rate,rateDate:quote.date,plannedAmount,dueDate:form.dueDate,frequency:form.frequency,priority:form.priority,notes:form.notes,status:remaining?'active':'paid'};if(editing)Object.assign(s.debts.find(x=>x.id===editing),record);else s.debts.push({id:id(),...record});return s},editing?'Repayment updated with latest rate':'Repayment added with latest rate');setEditing('');setForm(newDebtDraft(data.settings));setError('')}catch(err){setError(err.message)}}
  function pay(debt){const source=debt.sourceCurrency||base;requestMoney({title:`Record payment to ${debt.name}`,description:`Outstanding: ${formatMoney(debt.sourceRemaining??debt.remaining,source)}. The latest ${source} to ${base} rate will be applied when you save.`,currency:source,convertTo:base,label:`Payment amount in ${source}`,submitLabel:'Record payment',onSubmit:async sourceAmount=>{const quote=await getCurrencyQuote(source,base),amount=convertMinorUnits(sourceAmount,quote.rate);if(amount>debt.remaining)throw new Error('Payment cannot exceed the remaining balance.');return change(s=>{const d=s.debts.find(x=>x.id===debt.id);if(amount>d.remaining)throw new Error('Payment cannot exceed the remaining balance.');d.remaining-=amount;if(Number.isSafeInteger(d.sourceRemaining))d.sourceRemaining=Math.max(0,d.sourceRemaining-sourceAmount);if(!d.remaining)d.status='paid';s.debtPayments.push({id:id(),debtId:d.id,amount,sourceAmount,sourceCurrency:source,exchangeRate:quote.rate,rateDate:quote.date,date:today()});s.transactions.push({id:id(),title:`Payment to ${d.name}`,amount,type:'debt',categoryId:'',date:today(),note:`${formatMoney(sourceAmount,source)} at ${quote.rate}`,paymentMethod:'',createdAt:new Date().toISOString()});return s},'Payment recorded at the latest rate')}})}
  async function remove(item){if(!await confirmAction({title:'Delete money to pay back?',message:`“${item.name}” and its payment history will be permanently removed.`,confirmLabel:'Delete repayment'}))return;change(s=>{s.debts=s.debts.filter(x=>x.id!==item.id);s.debtPayments=s.debtPayments.filter(x=>x.debtId!==item.id);s.allocationRules=s.allocationRules.filter(x=>!(x.targetType==='debt'&&x.targetId===item.id));return s},'Repayment deleted')}
  return <div><div className="f-between"><div><h2 className="text-3xl font-bold">Money to Pay Back</h2><p className="f-help">Enter the debt in pounds, Pakistani rupees, Indian rupees, or another supported currency. The base-currency value uses the latest daily indicative rate.</p></div><span className="f-tag">Base: {base}</span></div><div className="f-grid f-stats mt-5"><Stat label={`Outstanding in ${base}`} amount={summary.outstanding} currency={base} tone="amber"/><Stat label="Paid this month" amount={summary.paidThisMonth} currency={base} tone="green"/><Stat label="Active repayments" text={String(data.debts.filter(d=>d.status==='active').length)}/></div>{error&&<p className="f-alert">{error}</p>}<div className="f-grid f-section-grid mt-5"><section className="f-list">{data.debts.length?data.debts.map(d=>{const source=d.sourceCurrency||base;return <article className="f-item" key={d.id}><div className="f-between"><div><p className="f-item-title">{d.name}</p><p className="f-meta">Due {d.dueDate||'date not set'} · {d.priority} priority · {d.status}{d.rateDate?` · rate ${d.rateDate}`:''}</p></div><span className="f-tag"><Money amount={d.remaining} currency={base}/> left</span></div>{source!==base&&<p className="f-conversion-line"><strong><Money amount={d.sourceRemaining??d.sourceOriginal} currency={source}/></strong> remaining in {source} · saved rate {Number(d.exchangeRate||0).toLocaleString(undefined,{maximumSignificantDigits:7})}</p>}<Progress value={d.original?Math.round((d.original-d.remaining)*10000/d.original):0}/><div className="f-actions mt-3"><button className="f-primary" disabled={!d.remaining} onClick={()=>pay(d)}>Record payment in {source}</button><button className={btn} onClick={()=>begin(d)}>Edit</button><button className={btn} onClick={()=>remove(d)}>Delete</button></div></article>}):<Empty>No repayments to track.</Empty>}</section><form className="f-card f-form" onSubmit={save}><h3>{editing?'Edit money to pay back':'Add money to pay back'}</h3><label>Person or organisation<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><div className="f-row"><label>Debt currency<select value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}><CurrencyOptions/></select></label><label>Original amount in {form.currency}<input required inputMode="decimal" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label></div>{preview.loading&&<p className="f-help" role="status">Getting latest rate…</p>}{preview.converted!=null&&<div className="f-conversion-preview"><span>Latest conversion</span><strong><Money amount={preview.converted} currency={base}/></strong><small>1 {form.currency} = {preview.quote.rate.toLocaleString(undefined,{maximumSignificantDigits:7})} {base} · rate date {preview.quote.date}</small></div>}{preview.error&&<p className="f-alert" role="alert">{preview.error}</p>}{editing&&<label>Amount left in {form.currency}<input required inputMode="decimal" value={form.remaining} onChange={e=>setForm({...form,remaining:e.target.value})}/></label>}<label>Due date<input type="date" value={form.dueDate} onChange={e=>setForm({...form,dueDate:e.target.value})}/></label><label>Planned payment amount in {base}<input inputMode="decimal" value={form.planned} onChange={e=>setForm({...form,planned:e.target.value})}/></label><div className="f-row"><label>Frequency<select value={form.frequency} onChange={e=>setForm({...form,frequency:e.target.value})}>{['weekly','fortnightly','monthly','yearly'].map(x=><option key={x}>{x}</option>)}</select></label><label>Priority<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{['low','medium','high'].map(x=><option key={x}>{x}</option>)}</select></label></div><div className="f-actions"><button className="f-primary" disabled={preview.loading}>{editing?'Save changes':'Add repayment'}</button>{editing&&<button type="button" className={btn} onClick={()=>{setEditing('');setForm(newDebtDraft(data.settings))}}>Cancel</button>}</div></form></div></div>
}

function DonationsManager({data,month,change,openTransaction,confirmAction}){const currency=data.settings.currency,donations=data.transactions.filter(t=>t.type==='donation'&&inMonth(t.date,month)),total=donations.reduce((s,t)=>s+t.amount,0),year=month.slice(0,4),yearTotal=data.transactions.filter(t=>t.type==='donation'&&t.date.startsWith(year)).reduce((s,t)=>s+t.amount,0);async function remove(donation){if(!await confirmAction({title:'Delete donation?',message:`“${donation.title}” will be permanently removed from your giving history.`,confirmLabel:'Delete donation'}))return;change(s=>{s.transactions=s.transactions.filter(x=>x.id!==donation.id);return s},'Donation deleted')}return <div><div className="f-between"><div><h2 className="text-3xl font-bold">Donations</h2><p className="f-help">Every gift is shown as a positive act.</p></div><button className="f-primary" onClick={()=>openTransaction({type:'donation'})}>＋ Record donation</button></div><div className="f-grid f-stats mt-5"><Stat label="This month" amount={total} currency={currency} tone="green"/><Stat label={`Total in ${year}`} amount={yearTotal} currency={currency} tone="green"/><Stat label="Donations this month" text={String(donations.length)}/></div><div className="f-list mt-5">{donations.length?donations.map(d=><div className="f-item f-between" key={d.id}><div><p className="f-item-title">{d.title}</p><p className="f-meta">{d.date}{d.note&&` · ${d.note}`}</p></div><div className="f-actions"><strong className="f-donation-amount">＋ <Money amount={d.amount} currency={currency}/></strong><button className={btn} onClick={()=>openTransaction(d)}>Edit</button><button className={btn} onClick={()=>remove(d)}>Delete</button></div></div>):<Empty>No donations recorded this month.</Empty>}</div></div>}

function CategoriesManager({data,change,confirmAction}){const blank={name:'',type:'expense',color:'#c5ff6f'},[form,setForm]=useState(blank),[editing,setEditing]=useState(''),[showArchived,setShowArchived]=useState(false),[error,setError]=useState('');const list=data.categories.filter(c=>showArchived||!c.archived).sort((a,b)=>a.order-b.order);async function save(e){e.preventDefault();try{await change(s=>{if(s.categories.some(c=>c.id!==editing&&c.name.toLowerCase()===form.name.trim().toLowerCase()))throw new Error('A category with this name already exists.');if(editing)Object.assign(s.categories.find(x=>x.id===editing),form,{name:form.name.trim()});else s.categories.push({id:id(),...form,name:form.name.trim(),icon:'',archived:false,order:s.categories.length});return s},editing?'Category updated':'Category added');setEditing('');setForm(blank);setError('')}catch(err){setError(err.message)}}async function remove(c){if(!await confirmAction({title:'Delete category?',message:`“${c.name}” will be removed. Old transactions remain, but their category will be cleared and related budget targets will be removed.`,confirmLabel:'Delete category'}))return;change(s=>{s.categories=s.categories.filter(x=>x.id!==c.id);s.transactions.forEach(x=>{if(x.categoryId===c.id)x.categoryId=''});for(const key of Object.keys(s.budgets))s.budgets[key]=s.budgets[key].filter(x=>x.categoryId!==c.id);return s},'Category deleted')}return <div className="f-grid f-section-grid"><section><div className="f-between"><div><h2 className="text-3xl font-bold">Categories</h2><p className="f-help">Edit, archive, or delete categories. Deleting keeps old transactions.</p></div><label className="font-semibold"><input type="checkbox" checked={showArchived} onChange={e=>setShowArchived(e.target.checked)}/> Show archived</label></div><div className="f-list mt-5">{list.map(c=><div className="f-item f-between" key={c.id}><div className="f-actions"><span aria-hidden="true" style={{width:'1rem',height:'1rem',borderRadius:'50%',background:c.color,border:'1px solid #111'}}/><div><p className="f-item-title">{c.name}</p><p className="f-meta">{typeLabels[c.type]||c.type}{c.archived?' · archived':''}</p></div></div><div className="f-actions"><button className={btn} onClick={()=>{setEditing(c.id);setForm({name:c.name,type:c.type,color:c.color})}}>Edit</button><button className={btn} onClick={()=>change(s=>{const x=s.categories.find(x=>x.id===c.id);x.archived=!x.archived;return s},c.archived?'Category restored':'Category archived')}>{c.archived?'Restore':'Archive'}</button><button className={btn} onClick={()=>remove(c)}>Delete</button></div></div>)}</div></section><form className="f-card f-form" onSubmit={save}><h3>{editing?'Edit category':'Add category'}</h3><label>Name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Type<select value={form.type} onChange={e=>setForm({...form,type:e.target.value})}>{transactionTypes.map(x=><option key={x} value={x}>{typeLabels[x]}</option>)}</select></label><label>Color<input type="color" value={form.color} onChange={e=>setForm({...form,color:e.target.value})}/></label>{error&&<p className="f-alert">{error}</p>}<div className="f-actions"><button className="f-primary">{editing?'Save changes':'Add category'}</button>{editing&&<button type="button" className={btn} onClick={()=>{setEditing('');setForm(blank)}}>Cancel</button>}</div></form></div>}

function BudgetManager({data,month,change,confirmAction}) {
  const currency=data.settings.currency,items=data.budgets[month]||[],summary=financeSummary(data,month),blank={categoryId:'',mode:'amount',value:''};
  const [draft,setDraft]=useState(blank),[editing,setEditing]=useState(''),[error,setError]=useState('');
  const categories=data.categories.filter(c=>!c.archived&&['expense','donation'].includes(c.type));
  async function save(e){e.preventDefault();try{const value=draft.mode==='amount'?parseMoney(draft.value):Math.round(Number(draft.value)*100);if(draft.mode==='percent'&&(!Number.isFinite(value)||value<=0||value>10000))throw new Error('Percentage must be between 0 and 100.');await change(s=>{s.budgets[month]||=[];const existing=editing?s.budgets[month].find(x=>x.id===editing):s.budgets[month].find(x=>x.categoryId===draft.categoryId);if(existing)Object.assign(existing,{categoryId:draft.categoryId,mode:draft.mode,value});else s.budgets[month].push({id:id(),categoryId:draft.categoryId,mode:draft.mode,value});return s},editing?'Budget target updated':'Budget target saved');setDraft(blank);setEditing('');setError('')}catch(err){setError(err.message)}}
  const actualFor=categoryId=>{const category=data.categories.find(c=>c.id===categoryId);return summary.transactions.filter(t=>t.type===(category?.type||'expense')&&t.categoryId===categoryId).reduce((a,t)=>a+t.amount,0)};
  async function remove(item,name){if(!await confirmAction({title:'Delete budget target?',message:`The ${name} target for ${month} will be permanently removed. Existing transactions stay unchanged.`,confirmLabel:'Delete target'}))return;change(s=>{s.budgets[month]=s.budgets[month].filter(x=>x.id!==item.id);return s},'Budget target deleted')}
  return <div><div className="f-between"><div><h2 className="text-3xl font-bold">Monthly Budget</h2><p className="f-help">Every target can be amended or removed.</p></div><button className={btn} disabled={!data.budgets[shiftMonth(month,-1)]} onClick={()=>change(s=>{s.budgets[month]=structuredClone(s.budgets[shiftMonth(month,-1)]||[]).map(x=>({...x,id:id()}));return s},'Previous budget copied')}>Copy previous month</button></div><div className="f-grid f-section-grid mt-5"><section>{items.length?<div className="f-list">{items.map(item=>{const cat=data.categories.find(c=>c.id===item.categoryId),target=budgetTarget(item,summary.income||data.settings.monthlyIncome),actual=actualFor(item.categoryId),used=target?Math.round(actual*10000/target):0,name=cat?.name||'Deleted category';return <article className="f-item" key={item.id}><div className="f-between"><div><p className="f-item-title">{name}</p><p className="f-meta">{item.mode==='percent'?`${(item.value/100).toFixed(1)}% of income`:'Fixed target'}</p></div><div className="f-actions"><button className={btn} onClick={()=>{setEditing(item.id);setDraft({categoryId:item.categoryId,mode:item.mode,value:item.mode==='amount'?moneyInput(item.value):String(item.value/100)})}}>Edit</button><button className={btn} onClick={()=>remove(item,name)}>Delete</button></div></div><div className="f-between mt-3"><span><Money amount={actual} currency={currency}/> used</span><strong><Money amount={target-actual} currency={currency}/> {target-actual>=0?'left':'over plan'}</strong></div><Progress value={used}/></article>})}</div>:<Empty>No targets for this month.</Empty>}</section><form className="f-card f-form" onSubmit={save}><h3>{editing?'Edit target':'Add a target'}</h3><label>Category<select required value={draft.categoryId} onChange={e=>setDraft({...draft,categoryId:e.target.value})}><option value="">Select category</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Target type<select value={draft.mode} onChange={e=>setDraft({...draft,mode:e.target.value,value:''})}><option value="amount">Fixed amount</option><option value="percent">Percentage of income</option></select></label><label>{draft.mode==='amount'?'Amount':'Percentage'}<input required inputMode="decimal" value={draft.value} onChange={e=>setDraft({...draft,value:e.target.value})}/></label>{error&&<p className="f-alert">{error}</p>}<div className="f-actions"><button className="f-primary">{editing?'Save changes':'Save target'}</button>{editing&&<button type="button" className={btn} onClick={()=>{setEditing('');setDraft(blank)}}>Cancel</button>}</div><p className="f-help">Planned total: <Money amount={summary.budgetPlanned} currency={currency}/></p></form></div></div>
}

function CurrencyCalculator({data}) {
  const [amount,setAmount]=useState('1'),[from,setFrom]=useState(data.settings.currency),[to,setTo]=useState(data.settings.defaultForeignCurrency||'PKR');
  const preview=useCurrencyPreview(amount,from,to);
  return <section className="f-converter"><div><span className="pill">Latest daily rates</span><h2 className="text-3xl font-bold mt-4">Currency Converter</h2><p className="f-help mt-2">Convert pounds, Pakistani rupees, Indian rupees, and other common currencies. No API key or subscription needed.</p></div><div className="f-card f-converter-card mt-5"><div className="f-form"><label>Amount<input autoFocus inputMode="decimal" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0.00"/></label><div className="f-converter-pair"><label>From<select value={from} onChange={e=>setFrom(e.target.value)}><CurrencyOptions/></select></label><button type="button" className={btn} onClick={()=>{setFrom(to);setTo(from)}} aria-label="Swap currencies">⇄ Swap</button><label>To<select value={to} onChange={e=>setTo(e.target.value)}><CurrencyOptions/></select></label></div></div><div className="f-converter-result" aria-live="polite">{preview.loading?<p>Getting latest rate…</p>:preview.error?<p className="f-negative">{preview.error}</p>:preview.converted!=null?<><span>{amount} {from} equals</span><strong><Money amount={preview.converted} currency={to}/></strong><small>1 {from} = {preview.quote.rate.toLocaleString(undefined,{maximumSignificantDigits:7})} {to} · rate date {preview.quote.date}</small></>:<p>Enter an amount to convert.</p>}</div></div><p className="f-help mt-4">Rates are indicative and update daily. Your bank or transfer provider may use a different rate or add fees.</p></section>
}

function CoreBiggerPicture({data,month}) {
  const currency=data.settings.currency,monthly=financeSummary(data,month),investments=investmentSummary(data.investments);
  const all=(type)=>data.transactions.filter(x=>x.type===type).reduce((sum,x)=>sum+x.amount,0);
  const goalsSaved=data.goals.reduce((sum,x)=>sum+x.saved,0),goalsTarget=data.goals.reduce((sum,x)=>sum+x.target,0);
  const debtOriginal=data.debts.reduce((sum,x)=>sum+x.original,0),debtLeft=data.debts.reduce((sum,x)=>sum+x.remaining,0),debtPaid=debtOriginal-debtLeft;
  return <section><div><span className="pill">Everything in one place</span><h2 className="text-3xl font-bold mt-4">Your Bigger Picture</h2><p className="f-help mt-2">Monthly movement and all-time progress across every money pot.</p></div><h3 className="f-picture-heading">This month</h3><div className="f-grid f-stats"><Stat label="Income" amount={monthly.income} currency={currency} tone="green"/><Stat label="Available now" amount={monthly.remaining} currency={currency} tone={monthly.remaining>=0?'blue':'pink'}/><Stat label="Saved" amount={monthly.savings} currency={currency}/><Stat label="Budget allocated" amount={monthly.budgetAllocated} currency={currency}/><Stat label="Goals funded" amount={monthly.goalContributions} currency={currency}/><Stat label="Donated" amount={monthly.donations} currency={currency} tone="green"/><Stat label="Invested" amount={monthly.investments} currency={currency}/><Stat label="Debt paid" amount={monthly.debtPayments} currency={currency}/></div><h3 className="f-picture-heading">All-time position</h3><div className="f-grid f-picture-grid"><article className="f-card"><h3>Savings</h3><strong className="f-big-number"><Money amount={all('savings')} currency={currency}/></strong><p className="f-help">Moved into savings pots</p></article><article className="f-card"><h3>Goals</h3><strong className="f-big-number"><Money amount={goalsSaved} currency={currency}/></strong><p className="f-help">of <Money amount={goalsTarget} currency={currency}/> across {data.goals.length} goal{data.goals.length===1?'':'s'}</p><Progress value={goalsTarget?Math.round(goalsSaved*10000/goalsTarget):0}/></article><article className="f-card"><h3>Investments</h3><strong className="f-big-number"><Money amount={investments.value} currency={currency}/></strong><p className="f-help"><Money amount={investments.contributed} currency={currency}/> contributed · <Money amount={investments.gain} currency={currency}/> gain/loss</p></article><article className="f-card"><h3>Money to pay back</h3><strong className="f-big-number"><Money amount={debtLeft} currency={currency}/> left</strong><p className="f-help"><Money amount={debtPaid} currency={currency}/> paid of <Money amount={debtOriginal} currency={currency}/></p><Progress value={debtOriginal?Math.round(debtPaid*10000/debtOriginal):0}/></article><article className="f-card"><h3>Giving</h3><strong className="f-big-number f-donation-amount">＋ <Money amount={all('donation')} currency={currency}/></strong><p className="f-help">Total donations recorded</p></article><article className="f-card"><h3>Monthly budgets</h3><strong className="f-big-number"><Money amount={monthly.budgetPlanned} currency={currency}/></strong><p className="f-help"><Money amount={monthly.expenses} currency={currency}/> spent against this month’s plan</p></article></div></section>
}

function BiggerPicture({data,month,change}) {
  const summary=financeSummary(data,month),currency=data.settings.currency,destination=data.settings.leftoverDestination||'rollover';
  const goal=data.goals.find(x=>x.id===data.settings.leftoverGoalId);
  const alreadyMoved=data.transactions.some(x=>x.allocationRuleId===`leftover-${month}`);
  async function moveLeftover(){if(summary.remaining<=0||destination==='rollover'||alreadyMoved)return;await change(s=>{applyAllocation(s,{id:`leftover-${month}`,name:`${month} leftover`,targetType:destination,targetId:destination==='goal'?goal?.id:'',mode:'amount',value:summary.remaining,note:`Month-end leftover from ${month}`},summary.income,`${month}-${new Date(Number(month.slice(0,4)),Number(month.slice(5,7)),0).getDate()}`);return s},'Month-end leftover moved')}
  return <><CoreBiggerPicture data={data} month={month}/><section className="f-card f-leftover mt-5"><div><span className="f-tag">Recommended home for unused income</span><h3 className="mt-3">Unallocated / rollover</h3><strong className="f-big-number"><Money amount={Math.max(0,summary.remaining)} currency={currency}/></strong><p className="f-help">This is real money still available, so it is not treated as spending. Keep it as a cash buffer, or choose Savings or a Goal in Finance Settings and move it when the month is finished.</p></div><div>{destination==='rollover'?<span className="f-tag">Will roll forward</span>:<button className="f-primary" disabled={summary.remaining<=0||alreadyMoved||(destination==='goal'&&!goal)} onClick={moveLeftover}>{alreadyMoved?'Leftover moved':`Move to ${destination==='goal'?(goal?.title||'chosen goal'):'savings'}`}</button>}</div></section></>
}

const blankRule = {name:'',targetType:'savings',targetId:'',categoryId:'',mode:'amount',value:'',timing:'income',day:'1',active:true};
function Automation({data,change,confirmAction}) {
  const [form,setForm]=useState(blankRule),[editing,setEditing]=useState(''),[error,setError]=useState('');
  const targetOptions=form.targetType==='goal'?data.goals:form.targetType==='investment'?data.investments:form.targetType==='debt'?data.debts:[];
  const categories=data.categories.filter(x=>!x.archived&&x.type===form.targetType);
  function begin(rule){setEditing(rule.id);setForm({...rule,value:rule.mode==='amount'?moneyInput(rule.value):String(rule.value/100)});}
  async function save(e){e.preventDefault();try{const value=form.mode==='amount'?parseMoney(form.value):Math.round(Number(form.value)*100);if(form.mode==='percent'&&(!value||value>10000))throw new Error('Percentage must be between 0 and 100.');if(['goal','investment','debt'].includes(form.targetType)&&!form.targetId)throw new Error('Choose where this deduction should go.');const record={...form,name:form.name.trim()||typeLabels[form.targetType],value,day:Number(form.day)||1};await change(s=>{if(editing)Object.assign(s.allocationRules.find(x=>x.id===editing),record);else s.allocationRules.push({id:id(),...record});return s},editing?'Automatic deduction updated':'Automatic deduction created');setEditing('');setForm(blankRule);setError('')}catch(err){setError(err.message)}}
  async function remove(rule){if(!await confirmAction({title:'Delete automatic deduction?',message:`“${rule.name}” will no longer run. Deductions already recorded stay in your history.`,confirmLabel:'Delete deduction'}))return;change(s=>{s.allocationRules=s.allocationRules.filter(x=>x.id!==rule.id);return s},'Automatic deduction deleted')}
  const rules=data.allocationRules||[];
  return <div className="f-grid f-section-grid"><section><h2 className="text-3xl font-bold">Automatic Deductions</h2><p className="f-help">Split income automatically, or choose a monthly deduction day. Monthly rules run the next time Finance is opened on or after that day.</p><div className="f-list mt-5">{rules.length?rules.map(rule=><article className="f-item" key={rule.id}><div className="f-between"><div><p className="f-item-title">{rule.name}</p><p className="f-meta">{typeLabels[rule.targetType]} · {rule.mode==='percent'?`${rule.value/100}% of income`:formatMoney(rule.value,data.settings.currency)} · {rule.timing==='income'?'when income is added':`monthly on day ${rule.day}`}</p></div><span className="f-tag">{rule.active?'On':'Paused'}</span></div><div className="f-actions mt-3"><button className={btn} onClick={()=>begin(rule)}>Edit</button><button className={btn} onClick={()=>change(s=>{const x=s.allocationRules.find(x=>x.id===rule.id);x.active=!x.active;return s},rule.active?'Deduction paused':'Deduction enabled')}>{rule.active?'Pause':'Enable'}</button><button className={btn} onClick={()=>remove(rule)}>Delete</button></div></article>):<Empty>No automatic deductions yet.</Empty>}</div></section><form className="f-card f-form" onSubmit={save}><h3>{editing?'Edit deduction':'Add automatic deduction'}</h3><label>Name<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="My payday split"/></label><label>Put money into<select value={form.targetType} onChange={e=>setForm({...form,targetType:e.target.value,targetId:'',categoryId:''})}>{allocationTargets.map(x=><option key={x} value={x}>{typeLabels[x]}</option>)}</select></label>{targetOptions.length>0&&<label>Choose {typeLabels[form.targetType].toLowerCase()}<select required value={form.targetId} onChange={e=>setForm({...form,targetId:e.target.value})}><option value="">Select one</option>{targetOptions.map(x=><option key={x.id} value={x.id}>{x.title||x.name}</option>)}</select></label>}{categories.length>0&&<label>Category (optional)<select value={form.categoryId} onChange={e=>setForm({...form,categoryId:e.target.value})}><option value="">Automatic</option>{categories.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>}<div className="f-row"><label>Amount type<select value={form.mode} onChange={e=>setForm({...form,mode:e.target.value,value:''})}><option value="amount">Fixed amount</option><option value="percent">Percentage of income</option></select></label><label>{form.mode==='amount'?'Amount':'Percentage'}<input required inputMode="decimal" value={form.value} onChange={e=>setForm({...form,value:e.target.value})}/></label></div><label>When to deduct<select value={form.timing} onChange={e=>setForm({...form,timing:e.target.value})}><option value="income">Whenever income is added</option><option value="monthly">On a day each month</option></select></label>{form.timing==='monthly'&&<label>Day of month<input type="number" min="1" max="28" value={form.day} onChange={e=>setForm({...form,day:e.target.value})}/></label>}{error&&<p className="f-alert">{error}</p>}<div className="f-actions"><button className="f-primary">{editing?'Save changes':'Create deduction'}</button>{editing&&<button type="button" className={btn} onClick={()=>{setEditing('');setForm(blankRule)}}>Cancel</button>}</div></form></div>
}

function Settings({data,change,close}){const [form,setForm]=useState({currency:data.settings.currency,income:moneyInput(data.settings.monthlyIncome),day:String(data.settings.budgetStartDay),defaultForeignCurrency:data.settings.defaultForeignCurrency||'PKR',leftoverDestination:data.settings.leftoverDestination||'rollover',leftoverGoalId:data.settings.leftoverGoalId||''}),[error,setError]=useState('');async function save(e){e.preventDefault();try{const monthlyIncome=form.income?nonNegativeMoney(form.income):0;if(form.leftoverDestination==='goal'&&!form.leftoverGoalId)throw new Error('Choose a goal for month-end leftover money.');const ok=await change(s=>{s.settings={...s.settings,currency:form.currency,monthlyIncome,budgetStartDay:Number(form.day),defaultForeignCurrency:form.defaultForeignCurrency,leftoverDestination:form.leftoverDestination,leftoverGoalId:form.leftoverDestination==='goal'?form.leftoverGoalId:'',configured:true};return s},'Finance settings saved');if(ok)close()}catch(err){setError(err.message)}}return <form className="f-form mt-5" onSubmit={save}><label>Base currency<select value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}><CurrencyOptions/></select></label><label>Default foreign currency<select value={form.defaultForeignCurrency} onChange={e=>setForm({...form,defaultForeignCurrency:e.target.value})}><CurrencyOptions/></select></label><p className="f-help">Used first when adding foreign-currency repayments or opening the converter.</p><label>Expected monthly income<input inputMode="decimal" value={form.income} onChange={e=>setForm({...form,income:e.target.value})}/></label><label>Budget start day<input type="number" min="1" max="28" value={form.day} onChange={e=>setForm({...form,day:e.target.value})}/></label><label>Unused income at month end<select value={form.leftoverDestination} onChange={e=>setForm({...form,leftoverDestination:e.target.value,leftoverGoalId:''})}><option value="rollover">Keep as unallocated / rollover (recommended)</option><option value="savings">Move to savings</option><option value="goal">Move to a goal</option></select></label>{form.leftoverDestination==='goal'&&<label>Leftover goal<select required value={form.leftoverGoalId} onChange={e=>setForm({...form,leftoverGoalId:e.target.value})}><option value="">Choose a goal</option>{data.goals.filter(x=>x.status!=='completed').map(x=><option key={x.id} value={x.id}>{x.title}</option>)}</select></label>}<p className="f-help">Rollover keeps the money available and does not falsely count it as spending. You can move it from Bigger Picture after the month is finished.</p>{error&&<p className="f-alert">{error}</p>}<button className="f-primary">Save settings</button></form>}

export function FinancePage(){
  const {data,busy,error,notice,setNotice,reload,change}=useFinance();
  const [tab,setTab]=useState('overview'),[month,setMonth]=useState(monthKey()),[dialog,setDialog]=useState(null);
  const {confirm:confirmAction,dialog:confirmation}=useConfirmDialog();
  const searchRef=useRef(null);
  const openTransaction=(initial=null)=>setDialog({type:'transaction',initial});
  const requestMoney=config=>setDialog({type:'money',config});
  useEffect(()=>{function keys(e){if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable="true"]'))return;if(e.key==='Escape')setDialog(null);if(e.key==='/'){e.preventDefault();setTab('transactions');setTimeout(()=>searchRef.current?.focus(),0)}const route={n:()=>openTransaction(),b:()=>setTab('budget'),g:()=>setTab('goals'),i:()=>setTab('investments')}[e.key.toLowerCase()];if(route){e.preventDefault();route()}}window.addEventListener('keydown',keys);return()=>window.removeEventListener('keydown',keys)},[]);
  useEffect(()=>{if(!data||busy||!data.settings.configured)return;const date=today(),currentMonth=monthKey(date),day=Number(date.slice(8,10));const due=(data.allocationRules||[]).some(rule=>rule.active&&rule.timing==='monthly'&&day>=Number(rule.day||1)&&!data.transactions.some(item=>item.allocationRuleId===rule.id&&inMonth(item.date,currentMonth)));if(due)change(s=>applyDueMonthlyAllocations(s,date),'Monthly automatic deductions applied')},[data,busy]);
  const body=useMemo(()=>{if(!data)return null;const props={data,month,setMonth,setTab,change,openTransaction,searchRef,requestMoney,confirmAction};return({overview:<Overview {...props}/>,timeline:<FinanceTimeline {...props}/>,picture:<BiggerPicture {...props}/>,transactions:<Transactions {...props}/>,budget:<BudgetManager {...props}/>,goals:<GoalsManager {...props}/>,investments:<InvestmentsManager {...props}/>,debts:<DebtsManager {...props}/>,converter:<CurrencyCalculator {...props}/>,donations:<DonationsManager {...props}/>,automation:<Automation {...props}/>,categories:<CategoriesManager {...props}/>})[tab]},[data,month,tab]);
  return <PageShell><section className="panel finance p-5 sm:p-8 lg:p-10"><AppNavigation activePath="/finance"/>{error&&<div className="f-alert" role="alert">{error} <button className={btn} disabled={busy} onClick={reload}>Retry</button></div>}{!data?<div className="f-card mt-8 font-bold">Loading Finance…</div>:!data.settings.configured?<Setup data={data} change={change}/>:<><header className="f-header"><div><span className="pill">Your money, clearly</span><h1 className="mt-5">Finance Manager</h1><p>Plan the month, record what happened, and keep your goals moving.</p></div><div className="f-actions"><button className="f-primary" disabled={busy} onClick={()=>openTransaction()}>＋ Add transaction <kbd className="f-kbd">N</kbd></button><button className={btn} onClick={()=>setDialog({type:'settings'})}>Settings</button></div></header><nav className="f-tabs mobile-section-nav" aria-label="Finance sections">{tabs.map(([key,label])=><button data-finance-tab={key} key={key} aria-pressed={tab===key} onClick={()=>setTab(key)}>{label}</button>)}</nav><FinanceQuickAdd data={data} disabled={busy} onReview={openTransaction}/>{body}<p className="f-help mt-6">Shortcuts: <kbd className="f-kbd">N</kbd> add · <kbd className="f-kbd">B</kbd> budget · <kbd className="f-kbd">G</kbd> goals · <kbd className="f-kbd">I</kbd> investments · <kbd className="f-kbd">/</kbd> search</p><button className="f-primary f-mobile-add" disabled={busy} onClick={()=>openTransaction()}>＋ Add transaction</button></>}{notice&&<button className="f-notice" onClick={()=>setNotice('')} aria-label="Dismiss message">{notice} · Dismiss</button>}{dialog?.type==='transaction'&&<Dialog title={dialog.initial?.id?'Edit transaction':dialog.initial?.aiReview?'Review AI transaction':'Add transaction'} close={()=>setDialog(null)}><TransactionForm data={data} initial={dialog.initial} close={()=>setDialog(null)} change={change}/></Dialog>}{dialog?.type==='settings'&&<Dialog title="Finance settings" close={()=>setDialog(null)}><Settings data={data} change={change} close={()=>setDialog(null)}/></Dialog>}{dialog?.type==='money'&&<Dialog title={dialog.config.title} close={()=>setDialog(null)}><MoneyActionForm config={dialog.config} close={()=>setDialog(null)}/></Dialog>}<ConfirmDialog isOpen={Boolean(confirmation)} {...confirmation}/></section></PageShell>
}
